<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php'; admin_required();
require __DIR__ . '/orders_beautiful.php'; exit;
$connection=db(); $status=(string)($_GET['status']??'all'); $q=trim((string)($_GET['q']??'')); $allowed=['all','new','confirmed','processing','ready','completed','cancelled']; if(!in_array($status,$allowed,true))$status='all';
$where=[];$types='';$params=[];if($status!=='all'){$where[]='o.status=?';$types.='s';$params[]=$status;}if($q!==''){$where[]='(o.order_number LIKE ? OR o.customer_name LIKE ? OR o.phone LIKE ?)';$types.='sss';$like='%'.$q.'%';array_push($params,$like,$like,$like);}
$sql="SELECT o.*,p.id payment_id,p.reference_number,p.proof_path,GROUP_CONCAT(CONCAT(oi.quantity,' x ',oi.product_name) ORDER BY oi.id SEPARATOR ', ') items FROM orders o LEFT JOIN payments p ON p.order_id=o.id LEFT JOIN order_items oi ON oi.order_id=o.id".($where?' WHERE '.implode(' AND ',$where):'').' GROUP BY o.id ORDER BY o.created_at DESC';$statement=$connection->prepare($sql);if($types!=='')$statement->bind_param($types,...$params);$statement->execute();$orders=$statement->get_result()->fetch_all(MYSQLI_ASSOC);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Orders | Sammy Tech</title><link rel="stylesheet" href="../assets/css/admin.css"><style>.orders{max-width:1400px;margin:auto;padding:32px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:20px;margin:14px 0}.toolbar,.actions,.top{display:flex;gap:12px;flex-wrap:wrap}.top{justify-content:space-between}.toolbar{align-items:end}.toolbar label{display:grid;gap:5px}.toolbar input,.toolbar select,.actions select,.actions button{padding:9px;border:1px solid #cbd5e1;border-radius:7px}.actions{margin-top:14px}.actions form{display:flex;gap:6px}.actions button,.download{background:#0f4c5c;color:#fff;border-color:#0f4c5c;padding:9px;border-radius:7px;text-decoration:none}.muted{color:#64748b}.pill{padding:4px 8px;border-radius:999px;background:#e0f2fe;text-transform:capitalize;font-size:12px}</style></head><body><main class="orders"><p><a href="index.php">&larr; Operations dashboard</a> | <a href="catalog.php">Products</a> | <a href="reports.php">Reports</a></p><h1>Order management</h1><p class="muted">Review customer orders, payment references, proof, delivery details, and stock-safe status changes.</p><form class="toolbar" method="get"><label>Find order or customer<input name="q" value="<?=e($q)?>" placeholder="Order number, name, phone"></label><label>Status<select name="status"><?php foreach($allowed as $option):?><option value="<?=e($option)?>" <?=$status===$option?'selected':''?>><?=e(ucfirst($option))?></option><?php endforeach;?></select></label><button>Filter orders</button><a class="download" href="export_orders.php">Download CSV</a></form><p class="muted"><?=count($orders)?> order(s) found.</p><?php foreach($orders as $order):?><article class="card"><div class="top"><div><h2><?=e($order['order_number'])?> <span class="pill"><?=e($order['status'])?></span></h2><p><b><?=e($order['customer_name'])?></b> | <?=e($order['phone'])?><?= $order['email']?' | '.e($order['email']):''?></p><p class="muted"><?=e(date('d M Y, H:i',strtotime($order['created_at'])))?> | <?=e(ucfirst($order['delivery_method']))?><?= $order['delivery_area']?': '.e($order['delivery_area']):''?></p></div><div><strong><?=money((float)$order['total_amount'])?></strong><p class="muted">Payment: <?=e($order['payment_status'])?></p></div></div><p><b>Items:</b> <?=e($order['items']?:'No items recorded')?></p><?php if($order['delivery_address']):?><p><b>Address:</b> <?=e($order['delivery_address'])?></p><?php endif;?><?php if($order['notes']):?><p><b>Customer note:</b> <?=e($order['notes'])?></p><?php endif;?><p><b>Payment:</b> <?=e(ucwords(str_replace('_',' ',$order['payment_method'])))?><?= $order['reference_number']?' | Reference: '.e($order['reference_number']):''?><?php if($order['proof_path']&&$order['payment_id']):?> | <a href="payment_proof.php?payment_id=<?=e((string)$order['payment_id'])?>" target="_blank">View payment proof</a><?php endif;?></p><div class="actions"><form action="order_action.php" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="order_id" value="<?=e((string)$order['id'])?>"><input type="hidden" name="action" value="status"><select name="status"><?php foreach(array_slice($allowed,1) as $option):?><option value="<?=e($option)?>" <?=$order['status']===$option?'selected':''?>><?=e(ucfirst($option))?></option><?php endforeach;?></select><button>Save order</button></form><form action="order_action.php" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="order_id" value="<?=e((string)$order['id'])?>"><input type="hidden" name="action" value="payment"><select name="payment_status"><?php foreach(['pending','paid','failed','refunded'] as $option):?><option value="<?=e($option)?>" <?=$order['payment_status']===$option?'selected':''?>><?=e(ucfirst($option))?></option><?php endforeach;?></select><button>Save payment</button></form></div></article><?php endforeach;?></main></body></html>
